('343a3501-3ba9-4501-a6f1-15b33cc6a6f7', 'sentence_completion', 'The little boy was ___ when he lost his favorite toy at the park.', NULL, '[{"id": "d", "text": "upset"}, {"id": "b", "text": "calm"}, {"id": "a", "text": "proud"}, {"id": "c", "text": "happy"}]'::jsonb, 0, '{"strategy": "lost his favorite toy = איבד את הצעצוע האהוב. איך מרגיש ילד שאיבד משהו חשוב?", "correct_reason": "upset = נסער. אובדן צעצוע אהוב מעציב ילד.", "options_analysis": ["נכון! upset = נסער — תגובה טבעית לאובדן", "calm = רגוע — פחות סביר לאובדן צעצוע אהוב", "proud = גאה — לא קשור לאובדן", "happy = שמח — הפוך מאובדן"]}', 1.37, -2.0, 0.25, 1, 'ai', NULL, true),
