('1647fb08-f1bf-4598-b8d8-06d79e568595', 'sentence_completion', 'The children were ___ after playing outside all afternoon.', NULL, '[{"id": "d", "text": "quiet"}, {"id": "b", "text": "clean"}, {"id": "c", "text": "bored"}, {"id": "a", "text": "dirty"}]'::jsonb, 3, '{"strategy": "playing outside all afternoon = משחקים בחוץ כל אחר הצהריים. איך נראים ילדים אחרי משחק בחוץ?", "correct_reason": "dirty = מלוכלכים. משחק בחוץ מלכלך ילדים.", "options_analysis": ["quiet = שקטים — הפוך, ילדים משחקים בקול", "clean = נקיים — הפוך, משחק בחוץ מלכלך", "bored = משועממים — הפוך, הם נהנו לשחק", "נכון! dirty = מלוכלכים — תוצאה טבעית של משחק בחוץ"]}', 1.49, -2.0, 0.25, 1, 'ai', NULL, true),
