('003b1549-9715-4220-beea-6908444d4870', 'sentence_completion', 'The puppy was ___ when it saw its owner come home.', NULL, '[{"id": "a", "text": "bored"}, {"id": "c", "text": "tired"}, {"id": "b", "text": "excited"}, {"id": "d", "text": "angry"}]'::jsonb, 2, '{"strategy": "saw its owner come home = ראה את הבעלים חוזר הביתה. איך מגיב כלבלב לבעלים?", "correct_reason": "excited = נרגש. כלבלבים נרגשים לראות את בעליהם.", "options_analysis": ["bored = משועמם — הפוך מהתרגשות", "tired = עייף — לא קשור", "נכון! excited = נרגש — תגובה טבעית של כלבלב", "angry = כועס — לא סביר לראיית בעלים"]}', 1.28, -2.0, 0.25, 1, 'ai', NULL, true),
('c1b2f13b-b9d7-473f-b428-3b4b2611d91c', 'sentence_completion', 'The shoes were ___ so she could not walk comfortably.', NULL, '[{"id": "a", "text": "new"}, {"id": "d", "text": "comfortable"}, {"id": "c", "text": "clean"}, {"id": "b", "text": "tight"}]'::jsonb, 3, '{"strategy": "could not walk comfortably = לא יכלה ללכת בנוחות. למה נעליים גורמות אי נוחות?", "correct_reason": "tight = צמודות מדי. נעליים צמודות מדי גורמות אי נוחות.", "options_analysis": ["new = חדשות — לא בהכרח גורם אי נוחות", "comfortable = נוחות — הפוך מאי נוחות", "clean = נקיות — לא קשור לנוחות", "נכון! tight = צמודות מדי — מסביר אי נוחות בהליכה"]}', 1.41, -2.0, 0.25, 1, 'ai', NULL, true),
