('bca42285-0fe4-443f-a9da-7a0047d7db90', 'restatement', 'The flowers grew tall because the gardener watered them every day.', NULL, '[{"id": "b", "text": "The gardener never watered the flowers."}, {"id": "c", "text": "The gardener watered the flowers every day, which made them grow tall."}, {"id": "d", "text": "The flowers stayed short despite daily watering."}, {"id": "a", "text": "The flowers grew tall even though no one watered them."}]'::jsonb, 1, '{"strategy": "grew tall because watered = גדלו גבוה כי הושקו. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר לגמרי — הגנן כן השקה", "נכון! אותה סיבה-תוצאה בדיוק", "סותר ''grew tall''", "סותר ''because the gardener watered them''"]}', 1.44, -2.0, 0.25, 1, 'ai', NULL, true),
