('1d51c626-a879-4898-83a5-dba4714d32cb', 'restatement', 'The man wore sunglasses because the sun was very bright.', NULL, '[{"id": "a", "text": "The man wore sunglasses even though it was cloudy."}, {"id": "d", "text": "It was dark, so the man wore sunglasses."}, {"id": "c", "text": "The man removed his sunglasses because the sun was bright."}, {"id": "b", "text": "The sun was very bright, so the man wore sunglasses."}]'::jsonb, 3, '{"strategy": "wore sunglasses because bright = לבש משקפי שמש כי היה בהיר. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["סותר ''the sun was very bright''", "הפוך — ''dark'' סותר ''bright''", "הפוך — ''removed'' סותר ''wore''", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.34, -2.0, 0.25, 1, 'ai', NULL, true),
