('06aca245-b35b-4f6e-80b6-a1f4d8683110', 'restatement', 'She felt nervous before the exam, but she performed well.', NULL, '[{"id": "b", "text": "She refused to take the exam because she was nervous."}, {"id": "d", "text": "Although she was nervous before the exam, she did well."}, {"id": "c", "text": "She was calm before the exam and performed poorly."}, {"id": "a", "text": "She felt nervous before the exam and performed poorly."}]'::jsonb, 1, '{"strategy": "nervous, but performed well = עצבנית, אך הצליחה. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר לגמרי — היא כן ניגשה למבחן", "נכון! אותה משמעות בדיוק: עצבנית אך הצליחה", "הפוך — ''calm'' סותר ''nervous''", "סותר ''performed well''"]}', 1.49, -2.0, 0.25, 1, 'ai', NULL, true),
