('d5181b7f-f65f-4d14-8469-d64905cb705e', 'restatement', 'He apologized to his friend for breaking the toy.', NULL, '[{"id": "b", "text": "His friend apologized for breaking the toy."}, {"id": "a", "text": "He refused to apologize for breaking the toy."}, {"id": "c", "text": "He broke the toy after apologizing."}, {"id": "d", "text": "He said sorry to his friend for breaking the toy."}]'::jsonb, 3, '{"strategy": "apologized for breaking = התנצל על שבירה. פעולה.", "correct_reason": "אותה פעולה בדיוק, ניסוח שונה.", "options_analysis": ["הפוך תפקידים — הוא התנצל, לא החבר", "סותר ''apologized''", "הופך את סדר האירועים", "נכון! אותה פעולה בדיוק: התנצל על שבירת הצעצוע"]}', 1.46, -2.0, 0.25, 1, 'ai', NULL, true),
('0651490b-2be1-4936-bd8f-58865afe0cbf', 'restatement', 'The waiter brought the food quickly, so the customers were pleased.', NULL, '[{"id": "d", "text": "The customers were pleased because the waiter brought the food quickly."}, {"id": "a", "text": "The customers were angry because the food came quickly."}, {"id": "c", "text": "The waiter brought the food slowly, so the customers were pleased."}, {"id": "b", "text": "The waiter forgot to bring the food."}]'::jsonb, 0, '{"strategy": "brought quickly, so pleased = הביא מהר, לכן היו מרוצים. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["נכון! אותה סיבה-תוצאה בדיוק", "סותר ''pleased''", "סותר ''quickly''", "סותר ''brought the food quickly''"]}', 1.36, -2.0, 0.25, 1, 'ai', NULL, true),
