('dbb99975-d0a2-486f-8ab1-f8d4f8e98834', 'restatement', 'The teacher smiled when the students answered correctly.', NULL, '[{"id": "c", "text": "The teacher frowned when the students answered correctly."}, {"id": "d", "text": "The teacher was angry when the students answered correctly."}, {"id": "a", "text": "The students smiled because the teacher answered correctly."}, {"id": "b", "text": "The teacher smiled because the students gave correct answers."}]'::jsonb, 3, '{"strategy": "smiled when answered correctly = חייכה כשענו נכון. סיבה-תוצאה.", "correct_reason": "אותה סיבה-תוצאה בדיוק.", "options_analysis": ["הפוך — ''frowned'' סותר ''smiled''", "סותר ''smiled''", "הפוך תפקידים — המורה חייכה, לא התלמידים", "נכון! אותה סיבה-תוצאה בדיוק"]}', 1.31, -2.0, 0.25, 1, 'ai', NULL, true),
