('ddb5376d-f49d-4446-91ce-946fed10caf6', 'reading_comprehension', 'When does Mr. Chen take his class to the garden?', '1b725fd5-ea19-464d-acd6-b85ee56e1a19', '[{"id": "b", "text": "Every Monday morning"}, {"id": "c", "text": "Every Friday afternoon"}, {"id": "a", "text": "Only at the end of the year"}, {"id": "d", "text": "Every day"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התדירות בפסקה.", "correct_reason": "הפסקה אומרת: ''Every Friday afternoon, Mr. Chen takes his class...to the school garden''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "זה קורה בסוף שנה כמסיבה, לא כביקור רגיל", "לא נאמר בפסקה"]}', 1.32, -2.0, 0.25, 1, 'ai', NULL, true),
('da529d59-231d-4ad3-baa1-335c6e79ea5a', 'reading_comprehension', 'What does Mr. Chen teach the students to do?', '1b725fd5-ea19-464d-acd6-b85ee56e1a19', '[{"id": "c", "text": "Paint pictures of flowers"}, {"id": "b", "text": "Build a new garden from scratch"}, {"id": "d", "text": "Water plants gently and remove weeds without hurting the roots"}, {"id": "a", "text": "Sell vegetables at the market"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את מה שמר צ''ן מלמד.", "correct_reason": "הפסקה אומרת: ''Mr. Chen teaches the students how to water the plants gently and remove weeds without hurting the roots''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה"]}', 1.39, -2.0, 0.25, 1, 'ai', NULL, true),
